TOKEN_MARKERS=re.compile(rb'(?i)(?:set-cookie|authorization|x-api-key|api[_-]key|access[_-]token|refresh[_-]token|client[_-]secret|x-csrf-token|x-xsrf-token|cookie\s*:)')
SAFE=re.compile(r'\[REDACTED[^\]]*\]',re.I)
PLACEHOLDER=re.compile(r'^(?:null|none|undefined|false|true|your[-_ ].*|example.*|test|dummy|token|secret|password|cookie|bearer|basic|\.\.\.|\$\{.*\}|\{\{.*\}\})$',re.I)
def sha(b):return hashlib.sha256(b).hexdigest()
def safe(v):return not v or bool(SAFE.fullmatch(v.strip()))
def valinfo(key,v):
 info={'header':key,'valueType':type(v).__name__}
 if isinstance(v,str):
  info['valueLength']=len(v)
  if key.lower() in {'set-cookie','cookie','cookies'}:
   names=[]
   for c in re.finditer(r'(?:^|[,;]\s*)([!#$%&\'*+.^_`|~0-9A-Za-z-]+)=',v):
    name=c.group(1)
    if name.lower() not in {'expires','max-age','domain','path','samesite','priority'} and name not in names:names.append(name)
   if names:info['cookieNames']=names
   domains=re.findall(r'(?i)(?:^|;)\s*domain=([.a-z0-9-]+)',v)
   if domains:info['cookieDomains']=sorted(set(domains))
   info['literalPlaceholder']=bool(PLACEHOLDER.fullmatch(v.strip()))
 return info
def pointer(k):return str(k).replace('~','~0').replace('/','~1')
def scan_bytes(data,name):
 out=[];parsed=False
 low=data.lower()
 if not any(k.encode() in low for k in SENSITIVE|GENERIC):return [],False,False
 try:text=data.decode('utf-8-sig')
 except UnicodeDecodeError:
  # Match headers in any bytes; decoding does not discard ASCII markers.
